    int n = height.size();
    if (n < 3) return 0;
    int totalWater = 0;

    for (int i = 1; i < n - 1; ++i) {
        int maxLeft = 0;
        for (int j = 0; j < i; ++j) {
            maxLeft = max(maxLeft, height[j]);
        }

        int maxRight = 0;
        for (int j = i + 1; j < n; ++j) {
            maxRight = max(maxRight, height[j]);
        }

        int waterLevel = min(maxLeft, maxRight);
        if (waterLevel > height[i]) {
            totalWater += waterLevel - height[i];
        }
    }
    return totalWater;
}

