int trap(vector<int>& height) {
    int n = height.size();
    if (n < 3) return 0;

    int left = 0, right = n - 1;
    int maxL = 0, maxR = 0;
    long long totalWater = 0;

    while (left < right) {
        if (height[left] < height[right]) {
            // Left side is the bottleneck
            if (height[left] >= maxL) {
                maxL = height[left];
            } else {
                totalWater += maxL - height[left];
            }
            left++;
        } else {
            // Right side is the bottleneck (or they are equal)
            if (height[right] >= maxR) {
                maxR = height[right];
            } else {
                totalWater += maxR - height[right];
            }
            right--;
        }
    }
    return totalWater;
}

